def tool(s,var,digest):
 p=Path(os.environ.get(var,''))
 if not p.is_absolute() or not p.is_file() or p.is_symlink() or hashlib.sha256(p.read_bytes()).hexdigest()!=digest:
  raise NativeEnvironmentUnavailable('SHA-bound official tool not provisioned: '+var)
 private=s.root/p.name;private.write_bytes(p.read_bytes());private.chmod(0o500)
 return private

def local(s,argv,timeout=15,allowed=(0,)):
 start=time.monotonic();p=subprocess.run([str(x) for x in argv],capture_output=True,timeout=timeout,cwd=s.root)
 row={'native_tool_argv':[str(x) for x in argv],'returncode':p.returncode,'stdout':p.stdout.decode(errors='replace'),'stderr':p.stderr.decode(errors='replace'),'seconds':time.monotonic()-start};s.trace.append(row)
 if p.returncode not in allowed:raise NativeEnvironmentUnavailable('official primitive/scanner tool failed: '+str(row))
 return p

def archive_lab(s):
 binary=tool(s,'OPSFORGE_DF_ARCHIVE_BIN',ARCHIVE_SHA)
 raw=io.BytesIO()
 with tarfile.open(fileobj=raw,mode='w',format=tarfile.USTAR_FORMAT) as t:
  directory=tarfile.TarInfo('folder');directory.type=tarfile.DIRTYPE;directory.mode=0o755;directory.mtime=0;directory.uid=directory.gid=0;t.addfile(directory)
  b=b'OpsForge-fixed-archive-member\n';h=tarfile.TarInfo('folder/data.txt');h.size=len(b);h.mode=0o640;h.mtime=0;h.uid=h.gid=0;t.addfile(h,io.BytesIO(b))
 zipped=io.BytesIO()
 with zipfile.ZipFile(zipped,'w') as z:z.writestr('folder/data.txt',b'OpsForge-fixed-archive-member\n')
 compressed=bz2.compress(raw.getvalue()) if s.probe_timeout==2 else gzip.compress(raw.getvalue(),mtime=0)
 samples={'plain.tar':raw.getvalue(),'disguised.zip':raw.getvalue(),'compressed.tar.data':compressed,'actual.zip':zipped.getvalue(),'plain-text.gz':gzip.compress(b'not a tar archive\n',mtime=0)}
 results={}
 for name,data in samples.items():
  p=s.root/name;p.write_bytes(data);dest=s.root/(name+'-unpacked');dest.mkdir()
  value=json.loads(local(s,[binary,p,dest]).stdout);expected=name in ('plain.tar','disguised.zip','compressed.tar.data')
  assert value['is_tar'] is expected and value['build_executed'] is False
  if expected:assert value['files']==[{'path':'folder/data.txt','mode':'0640','size':len(b'OpsForge-fixed-archive-member\n'),'content':'OpsForge-fixed-archive-member\n'}]
  results[name]={'sha256':hashlib.sha256(data).hexdigest(),**value}
 return {'official_archive_primitive':results,'actual_ADD_build_executed':False,'scope':'official Moby archive detection/untar only; ADD behavior interpreted from versioned Dockerfile specification'}

