 return {'image_store_id':image['Id'],'repo_digests':image['RepoDigests'],'config_bytes_sha256':hashlib.sha256(config).hexdigest(),'docker_save_sha256':hashlib.sha256(saved.read_bytes()).hexdigest(),'all_layers':layerinfo,'scanner_findings':findings,'synthetic_positive_findings':controls,'missing_upstream_materials':['build-logs','build-cache','provenance','secret-input-flow'],'image_secret_free_proven':False,'release_gate':'reject-incomplete-evidence','scanner_scope':'all saved layer regular files plus actual config/history; pattern scanner does not prove absence'}

