def request(s,client,url,expected=None,success=True):
 p=s.call(['exec',client,'wget','-q','-T',str(s.probe_timeout),'-O','-',url],check=False,timeout=4)
 if success:assert p.returncode==0 and (expected is None or p.stdout==expected.encode())
 else:assert p.returncode!=0
 return {'url':url,'returncode':p.returncode,'stdout':p.stdout.decode(errors='replace')}

def business_lab(s,stages=1,label='business'):
 net=s.network(label,internal=True);client=s.launch(label+'-client',net);rows=[]
 for i in range(stages):
  revision='lab-stage-'+str(i);name=s.launch(label+str(i),net,['/bin/sh','-c',HTTP_SCRIPT],extra=['--user','1000:1000','--read-only','--tmpfs','/tmp:rw,nosuid,nodev,noexec,size=2m,mode=1777','-e','CONFIG_REV='+revision,'-e','BUSINESS_TOKEN='+s.token])
  ip=s.obj('container',name)['NetworkSettings']['Networks'][net]['IPAddress'];url='http://'+ip+':8080/'
  for attempt in range(15):
   try:normal=request(s,client,url,s.token);break
   except AssertionError:time.sleep(.1)
  else:raise NativeEnvironmentUnavailable('owned BusyBox HTTP business fixture did not start')
  config=request(s,client,url+'revision.txt',revision)
  uid=s.call(['exec',name,'id','-u']).stdout.decode().strip();assert uid=='1000'
  refused=s.call(['exec',name,'touch','/root-write-forbidden'],check=False);assert refused.returncode!=0
  writable=s.call(['exec',name,'touch','/tmp/allowed-write']);assert writable.returncode==0
  refused_unused_port=request(s,client,'http://'+ip+':1/',success=False)
  inspect=s.obj('container',name);assert inspect['HostConfig']['ReadonlyRootfs'] and inspect['Config']['Image']==s.image
  s.call(['stop','--time','3',name]);stopped=s.obj('container',name);assert stopped['State']['ExitCode']==0
  logs=s.call(['logs',name]);assert b'STOP_ACK' in logs.stdout
  rows.append({'stage':revision,'image_store_id':inspect['Image'],'approved_immutable_ref':inspect['Config']['Image'],'uid':uid,'readonly_root_rejection':refused.returncode,'writable_tmp':True,'normal_business':normal,'configuration_observed':config,'unused_port_connection_refused':refused_unused_port,'real_application_dependency_failure_tested':False,'actual_graceful_stop_exit':stopped['State']['ExitCode'],'production_stage':False})
 # Recreate approved prior configuration using same immutable artifact, and actually observe it.
 rollback=s.launch(label+'-rollback',net,['/bin/sh','-c',HTTP_SCRIPT],extra=['--user','1000:1000','--read-only','--tmpfs','/tmp:rw,size=2m,mode=1777','-e','CONFIG_REV=lab-stage-0','-e','BUSINESS_TOKEN='+s.token])
 for attempt in range(15):
  try:restored=request(s,client,'http://'+rollback+':8080/revision.txt','lab-stage-0');break
  except AssertionError:time.sleep(.1)
 else:raise NativeEnvironmentUnavailable('owned config rollback unavailable')
 return {'lab_stages':rows,'configuration_rollback':restored,'application_fixture':'BusyBox standard httpd with own token/config; not enterprise business or rebuilt image','script_sha256':hashlib.sha256(HTTP_SCRIPT.encode()).hexdigest(),'source_build_attestation_verified':False,'production_approval_or_deployment':False,'TLS_probe_and_database_not_executed':True}

