def upgrade_lab(s):
 old=business_lab(s)
 other='docker.io/library/busybox@sha256:a7dbc319b1438115a207e11930dc4bb3e643dcb3ec0bdd694bb36cd8fad289ec'
 new=s.obj('image',other);approved=s.image;s.image=other
 try:updated=business_lab(s,label='updated')
 finally:s.image=approved
 assert s.image_id!=new['Id'],'upgrade lab requires two actual different immutable artifacts'
 versions=[]
 for i,ref in enumerate((approved,other)):
  oldimage=s.image;s.image=ref
  try:c=s.launch('version'+str(i),command=['/bin/sh','-c','busybox | head -n 1; sleep 300'])
  finally:s.image=oldimage
  versions.append(s.call(['logs',c]).stdout.decode().strip())
 assert versions[0]!=versions[1]
 return {'old':old,'new':updated,'old_new_component_versions':versions,'old_new_ids':[s.image_id,new['Id']],'TLS_and_advisory_vulnerability_scanner_pending':True,'production_canary_executed':False,'recreated_prior_artifact_config':True}

