def run(qid):
 s=Owned();observed={};lab_complete=False;blocked=None
 try:
  s.enter();s.probe_timeout=1
  try:
   submitted=json.loads(Path('design.json').read_text());v=submitted.get('probe_timeout_seconds')
   if type(v) is int and v in (1,2):s.probe_timeout=v
  except (ValueError,AttributeError):pass
  if qid.endswith('w-048'):observed=archive_lab(s)
  elif qid.endswith('-064') or qid.endswith('-089'):observed=image_evidence(s)
  elif qid.endswith('-091'):observed=business_lab(s,3)
  elif qid.endswith('-092'):observed=isolation_lab(s)
  elif qid.endswith('-099'):observed=retag_lab(s)
  elif qid.endswith('-095'):observed=no_shell_lab(s)
  elif qid.endswith('-093'):observed=upgrade_lab(s)
  elif qid.endswith('-094'):observed=timing_lab(s)
  else:observed=business_lab(s)
  write_audit_atomic(Path('dfknowledge-observation.json'),{'question_id':qid,'native_observed':observed,'not_a_full_production_or_build_acceptance':True})
  s.trace.append({'dfknowledge_observation':observed})
  lab_complete=True
  validate(qid)
  print('PASS: ORIGINAL_DESIGN_SEMANTICS_AND_DECLARED_NATIVE_SCOPE',flush=True)
 except Exception as exc:
  if lab_complete:raise
  s.ready=False;blocked=exc
  s.trace.append({'native_lab_incomplete':True,'exception_type':type(exc).__name__,'detail':str(exc),'not_a_learner_rejection':True})
 finally:s.finish()
 if blocked:
  print('NATIVE_ENVIRONMENT_OR_FIXTURE_UNAVAILABLE:'+repr(blocked),flush=True);raise SystemExit(78)

def validate(qid):
 from dfknowledge_contracts import CONTRACTS
 contract=CONTRACTS[qid];p=Path('design.json');st=p.lstat();assert stat.S_ISREG(st.st_mode) and st.st_nlink==1 and st.st_size<65536
 got=json.loads(p.read_text(),object_pairs_hook=unique_object);assert isinstance(got,dict) and set(got)==set(contract['reference']),'all public design fields required'
 aliases=contract.get('aliases',{})
 def normalized(v):
  if isinstance(v,str):return aliases.get(v,v)
  if isinstance(v,list):return sorted((normalized(x) for x in v),key=lambda x:json.dumps(x,sort_keys=True))
  if isinstance(v,dict):return {k:normalized(x) for k,x in v.items()}
  return v
 assert type(got['probe_timeout_seconds']) is int and got['probe_timeout_seconds'] in (1,2),'approved bounded probe fixture alternatives are 1 or 2 seconds'
 expected=dict(contract['reference']);expected['probe_timeout_seconds']=got['probe_timeout_seconds']
 assert json.dumps(normalized(got),sort_keys=True)==json.dumps(normalized(expected),sort_keys=True),'original design requirements / evidence boundaries / failure gates not satisfied'

