def request(s,client,url,expected=None,success=True):
 p=s.call(['exec',client,'wget','-q','-T',str(s.probe_timeout),'-O','-',url],check=False,timeout=4)
 if success:assert p.returncode==0 and (expected is None or p.stdout==expected.encode())
 else:assert p.returncode!=0
 return {'url':url,'returncode':p.returncode,'stdout':p.stdout.decode(errors='replace')}

